<?php require_once __DIR__.'/../../config/bootstrap.php'; require_internal(); $pdo=db();$pageTitle='Categorias';$error='';
if($_SERVER['REQUEST_METHOD']==='POST'){check_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);$nome=trim($_POST['nome']??'');try{if($a==='save'&&$nome!==''){if($id)$pdo->prepare('UPDATE categorias SET nome=? WHERE id=?')->execute([$nome,$id]);else$pdo->prepare('INSERT INTO categorias(nome,criado_em) VALUES(?,?)')->execute([$nome,now()]);flash('success','Categoria salva com sucesso.');}elseif($a==='toggle'){$pdo->prepare('UPDATE categorias SET ativo=CASE ativo WHEN 1 THEN 0 ELSE 1 END WHERE id=?')->execute([$id]);flash('success','Status atualizado.');}}catch(Throwable $e){$error='Não foi possível salvar a categoria.';}}
$rows=$pdo->query('SELECT * FROM categorias ORDER BY ativo DESC,nome')->fetchAll();include __DIR__.'/../../includes/header.php'; ?><div class="page-head"><div><h1>Categorias</h1></div></div><div class="grid grid-2"><div class="card"><h3>Nova categoria</h3><?php if($error): ?><div class="alert danger"><?=e($error)?></div><?php endif; ?><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="save"><div class="field"><label>Nome</label><input name="nome" required></div><div class="form-actions"><button class="btn primary">Salvar</button></div></form></div><div class="card"><h3>Lista</h3><div class="table-wrap"><table class="table"><thead><tr><th>Categoria</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?=e($r['nome'])?></td><td><?=status_badge($r['ativo']?'Ativa':'Inativa')?></td><td><form method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?=$r['id']?>"><button class="btn small secondary">Alternar</button></form></td></tr><?php endforeach; ?></tbody></table></div></div></div><?php include __DIR__.'/../../includes/footer.php'; ?>
